import React, { useState, useEffect } from 'react';
import api from '../services/api';
import GameCard from '../components/Store/GameCard';
import './HomePage.css';

const HomePage = () => {
  const [games, setGames] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [connectionStatus, setConnectionStatus] = useState('checking');
  
  // Состояния карусели
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isAutoPlaying, setIsAutoPlaying] = useState(true);
  const AUTO_PLAY_INTERVAL = 5000; // 5 секунд

  useEffect(() => {
    testConnection();
  }, []);

  // Автопрокрутка
  useEffect(() => {
    if (!isAutoPlaying || games.length <= 1) return;
    const timer = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % games.length);
    }, AUTO_PLAY_INTERVAL);
    return () => clearInterval(timer);
  }, [isAutoPlaying, games.length]);

  const testConnection = async () => {
    try {
      setConnectionStatus('checking');
      const response = await api.get('/games');
      setGames(response.data);
      setConnectionStatus('connected');
      setLoading(false);
    } catch (err) {
      setConnectionStatus('error');
      setError(err.message);
      setLoading(false);
    }
  };

  const nextSlide = () => {
    setCurrentIndex((prev) => (prev + 1) % games.length);
    pauseAutoPlay();
  };

  const prevSlide = () => {
    setCurrentIndex((prev) => (prev - 1 + games.length) % games.length);
    pauseAutoPlay();
  };

  const goToSlide = (index) => {
    setCurrentIndex(index);
    pauseAutoPlay();
  };

  const pauseAutoPlay = () => {
    setIsAutoPlaying(false);
    // Возобновляем автопрокрутку через 8 сек после ручного действия
    setTimeout(() => setIsAutoPlaying(true), 8000);
  };

  // Рендер карусели
  const renderCarousel = () => {
    if (loading || games.length === 0) {
      return (
        <div className="carousel-container carousel-loading">
          <p>{loading ? 'Загрузка баннеров...' : 'Нет игр для отображения'}</p>
        </div>
      );
    }

    const currentGame = games[currentIndex];
    // Замените `cover_image` на поле, которое используется в вашем API
    const imageUrl = currentGame.cover_image || currentGame.image_url || 'https://via.placeholder.com/1200x450/1b2838/66c0f4?text=No+Cover';

    return (
      <div 
        className="carousel-container" 
        onMouseEnter={() => setIsAutoPlaying(false)}
        onMouseLeave={() => setIsAutoPlaying(true)}
      >
        <div className="carousel-slide active">
          <img src={imageUrl} alt={currentGame.name} className="carousel-image" />
          <div className="carousel-overlay">
            <div className="carousel-content">
              <h2>{currentGame.name}</h2>
              <p className="carousel-desc">{currentGame.description?.slice(0, 120)}...</p>
              <div className="carousel-actions">
                <span className="carousel-price">₽{currentGame.price ?? '0.00'}</span>
                <button className="carousel-cta-btn">Подробнее</button>
              </div>
            </div>
          </div>
        </div>

        {/* Стрелки */}
        <button className="carousel-btn prev" onClick={prevSlide} aria-label="Предыдущая игра">&#10094;</button>
        <button className="carousel-btn next" onClick={nextSlide} aria-label="Следующая игра">&#10095;</button>

        {/* Точки навигации */}
        <div className="carousel-dots">
          {games.map((_, idx) => (
            <button
              key={idx}
              className={`carousel-dot ${idx === currentIndex ? 'active' : ''}`}
              onClick={() => goToSlide(idx)}
              aria-label={`Перейти к игре ${idx + 1}`}
            />
          ))}
        </div>
      </div>
    );
  };

  return (
    <div className="home-page">
      {/* Баннер подключения */}
      <div className={`connection-banner ${connectionStatus}`}>
        <div className="banner-content">
          {connectionStatus === 'checking' && (
            <>
              <span className="status-icon">⏳</span>
              <span>Подключение к серверу...</span>
            </>
          )}
          {connectionStatus === 'connected' && (
            <>
              <span className="status-icon">✅</span>
              <span>Сервер подключён! API работает корректно.</span>
            </>
          )}
          {connectionStatus === 'error' && (
            <>
              <span className="status-icon">❌</span>
              <span>Ошибка подключения: {error}</span>
              <button onClick={testConnection} className="retry-btn">Повторить</button>
            </>
          )}
        </div>
      </div>

      {/* Карусель игр (Steam-style) */}
      <section className="featured-carousel">
        {renderCarousel()}
      </section>

      {/* Статистика */}
      <section className="stats-section">
        <div className="stat-card">
          <h3>🎮 Игр доступно</h3>
          <p className="stat-number">{games.length}</p>
        </div>
        <div className="stat-card">
          <h3>🖥️ Статус сервера</h3>
          <p className={`stat-number ${connectionStatus}`}>
            {connectionStatus === 'connected' ? 'Онлайн' : 'Оффлайн'}
          </p>
        </div>
        <div className="stat-card">
          <h3>🌐 API URL</h3>
          <p className="stat-url">http://localhost:5000/api</p>
        </div>
      </section>

      {/* Список игр */}
      <section className="games-section">
        <h2>🔥 Доступные игры</h2>
        {loading ? (
          <div className="loader">Загрузка...</div>
        ) : games.length > 0 ? (
          <div className="games-grid">
            {games.map((game) => (
              <GameCard key={game.id} game={game} />
            ))}
          </div>
        ) : (
          <div className="empty-state">
            <p>📭 В базе данных пока нет игр</p>
            <p className="hint">Добавьте игры через PostgreSQL или Swagger</p>
          </div>
        )}
      </section>

      {/* Информация для разработчика */}
      <section className="dev-info">
        <h2>🛠️ Информация для разработки</h2>
        <div className="info-grid">
          <div className="info-card">
            <h4>Frontend</h4>
            <p>React 18</p>
            <p>Порт: 3000</p>
          </div>
          <div className="info-card">
            <h4>Backend</h4>
            <p>ASP.NET Core 10</p>
            <p>Порт: 5000</p>
          </div>
          <div className="info-card">
            <h4>Database</h4>
            <p>PostgreSQL</p>
            <p>Порт: 5432</p>
          </div>
          <div className="info-card">
            <h4>Swagger</h4>
            <p>
              <a href="http://localhost:5000/swagger" target="_blank" rel="noreferrer">
                http://localhost:5000/swagger
              </a>
            </p>
          </div>
        </div>
      </section>
    </div>
  );
};

export default HomePage;
